import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.RemoveVolumeEntity{EntityRuntimeID: 7, Dimension: -1}
NEGATIVE_DIMENSION = bytes.fromhex("0701")

# generated by gophertunnel b8bd735:
# &packet.RemoveVolumeEntity{EntityRuntimeID: 300, Dimension: 2}
LARGE_NET_ID = bytes.fromhex("ac0204")

GOLDENS = [
    pytest.param(
        v2225.RemoveVolumeEntityPacket(entity_net_id=7, dimension_type=-1), NEGATIVE_DIMENSION, id="negative-dimension"
    ),
    pytest.param(v2225.RemoveVolumeEntityPacket(entity_net_id=300, dimension_type=2), LARGE_NET_ID, id="large-net-id"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_remove_volume_entity_is_packet_167(version):
    assert version.PACKETS[167] is version.RemoveVolumeEntityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_volume_entity_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_volume_entity_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
